pthread_t tid;

void* thread_func(void* arg) {
    int data = *(int*)arg;
    // Calculation...
    return (void*)(long)(data + 1);
}

int main_data = 100;
void* status;

// Create: &ID, Attributes (NULL), Routine, Arguments
pthread_create(&tid, NULL, thread_func, &main_data);

// Wait for thread termination and capture status
pthread_join(tid, &status);

int result = (int)(long)status; // 101
// Use result
// ...
// Must use pthread_exit in main if other threads are running
// pthread_exit(NULL);
// ...
